import{_ as e,a}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as r}from"./chunks/ts-mic-privacy.DXgfNaDe.js";import{_ as d,o as n,c as o,ag as h}from"./chunks/framework.DTisvaUJ.js";const C=JSON.parse('{"title":"困ったときの対処 — 音が出ない・認識されないとき","description":"Mutelinkで読み上げの音が出ない、マイクが認識されない、VRChatに文字が送れないときの確認手順と対処方法を案内します。","frontmatter":{"title":"困ったときの対処 — 音が出ない・認識されないとき","description":"Mutelinkで読み上げの音が出ない、マイクが認識されない、VRChatに文字が送れないときの確認手順と対処方法を案内します。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"困ったときの対処 — 音が出ない・認識されないとき | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkで読み上げの音が出ない、マイクが認識されない、VRChatに文字が送れないときの確認手順と対処方法を案内します。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"困ったときの対処 — 音が出ない・認識されないとき | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkで読み上げの音が出ない、マイクが認識されない、VRChatに文字が送れないときの確認手順と対処方法を案内します。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}]]},"headers":[],"relativePath":"help/troubleshooting.md","filePath":"help/troubleshooting.md"}'),i={name:"help/troubleshooting.md"};function l(s,t,u,b,p,g){return n(),o("div",null,[...t[0]||(t[0]=[h('<h1 id="困ったときの対処" tabindex="-1">困ったときの対処 <a class="header-anchor" href="#困ったときの対処" aria-label="Permalink to &quot;困ったときの対処&quot;">​</a></h1><p>よくある問題と、確認する順番です。上から順に試してください。ここに載っていないときは、アプリの 設定 &gt; そのほか &gt; アプリについて の「不具合・要望を送る」から知らせてください。</p><h2 id="読み上げの声が出ない" tabindex="-1">読み上げの声が出ない <a class="header-anchor" href="#読み上げの声が出ない" aria-label="Permalink to &quot;読み上げの声が出ない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>メイン画面の読み上げ(合成音声)のボタンがオンか</td><td>オフだと読み上げません。押してオンにします</td></tr><tr><td>読み上げの声を選んでいるか</td><td>出力の言語に、読み上げの声(VOICEVOX、Irodori-TTS、Qwen3-TTS)が選ばれているか確認します。「なし」だと、チャットボックスにだけ送ります</td></tr><tr><td>声のダウンロードが済んでいるか</td><td>設定 &gt; そのほか &gt; モデルと容量 で、使う声が入っているか確認します。VOICEVOXは、キャラクターも選びます</td></tr><tr><td>スピーカーの出力先と音量</td><td>設定 &gt; 送る &gt; 読み上げの基本 の「スピーカー」で、出力先と、デバイスごとの音量を確認します</td></tr><tr><td>翻訳した文を読み上げようとしていないか</td><td>訳した文の読み上げは、<a href="/Mutelink-releases/about/supporter">支援版</a>の機能です。ライセンスが無いときは、チャットボックスにだけ送られます</td></tr><tr><td>その言語を読める声か</td><td>VOICEVOXとIrodori-TTSは日本語だけ、Qwen3-TTSは10言語です。読める声が無い言語は、チャットボックスにだけ送ります</td></tr><tr><td>「VRAMがいっぱいなので、AI音声をオフにしました」と出た</td><td>GPUのメモリが足りなくなったため、読み上げが自動でオフになり、文はチャットボックスに出るようになりました。自動では戻らないので、余裕ができたら、読み上げ(TTS)のボタンをオンにします(同じ声に戻ります)</td></tr></tbody></table><h2 id="vrchatの相手に声が届かない" tabindex="-1">VRChatの相手に声が届かない <a class="header-anchor" href="#vrchatの相手に声が届かない" aria-label="Permalink to &quot;VRChatの相手に声が届かない&quot;">​</a></h2><p>自分のスピーカーでは読み上げが聞こえるのに、相手に届かないときです。</p><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>VB-Audio Virtual Cableが入っているか</td><td>Windowsのサウンドの設定に「CABLE Input」と「CABLE Output」があるか確認します。無ければ<a href="/Mutelink-releases/guide/getting-started#_1-vb-audio-virtual-cableを入れる">インストール</a>します</td></tr><tr><td>Mutelinkの出力先に「CABLE Input」があるか</td><td>設定 &gt; 送る &gt; 読み上げの基本 の「スピーカー」で、「CABLE Input」を選びます。一覧に無いときは、「デバイス一覧を更新」を押すか、Mutelinkを起動し直します</td></tr><tr><td>VRChatのマイクが「CABLE Output」か</td><td>VRChatの 設定 &gt; オーディオ で確認します</td></tr><tr><td><strong>VRChatのマイクを、選び直したか</strong></td><td>「CABLE Output」になっていても届かないときは、VRChatのマイクを一度ほかのデバイスに変えてから、「CABLE Output」に戻します。VRChatは起動したときのデバイスをつかんだままなので、あとから入れたり変えたりしたケーブルは、選び直すまで使われません(VRChatを起動し直しても直ります)</td></tr><tr><td>VRChatでミュートになっていないか</td><td>VRChatの中で、マイクのミュートを解除します</td></tr><tr><td>Mutelinkのマイクに「CABLE Output」を選んでいないか</td><td>Mutelinkのマイクには、実際のマイクを選びます</td></tr></tbody></table><p><img src="'+e+'" alt="VRChatのマイクが「CABLE Output」か"></p><h2 id="自分には読み上げが聞こえない" tabindex="-1">自分には読み上げが聞こえない <a class="header-anchor" href="#自分には読み上げが聞こえない" aria-label="Permalink to &quot;自分には読み上げが聞こえない&quot;">​</a></h2><p>出力先が「CABLE Input」だけだと、相手には聞こえますが、自分には聞こえません。設定 &gt; 送る &gt; 読み上げの基本 の「スピーカー」で、「CABLE Input」と、自分のスピーカーやヘッドホンの両方を選びます。デバイスごとに音量を変えられます。</p><h2 id="vrchatに文字が出ない" tabindex="-1">VRChatに文字が出ない <a class="header-anchor" href="#vrchatに文字が出ない" aria-label="Permalink to &quot;VRChatに文字が出ない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>VRChatのOSCが有効か</td><td>リングメニュー &gt; Options &gt; OSC &gt; Enabled にします</td></tr><tr><td>メイン画面のチャットボックスのボタンがオンか</td><td>オフだと、チャットボックスには送られません</td></tr><tr><td>文を送ったか</td><td>自動で送る設定がオフのときは、認識されただけでは送られません。送信の操作をします</td></tr><tr><td>声が出てから文字を出す設定にしていないか</td><td>設定 &gt; 送る &gt; 読み上げの基本 で「声が出始めてから出す」にしていると、声が出るまで(最大8秒)文字は出ません</td></tr><tr><td>VRChat側でチャットボックスを非表示にしていないか</td><td>VRChatの設定を確認します</td></tr></tbody></table><p><img src="'+a+'" alt="VRChatのOSCが「Enabled」か"></p><h2 id="音声認識が動かない・途切れる" tabindex="-1">音声認識が動かない・途切れる <a class="header-anchor" href="#音声認識が動かない・途切れる" aria-label="Permalink to &quot;音声認識が動かない・途切れる&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>音声認識がオンか</td><td>メイン画面の音声認識のボタンがオフだと、認識しません</td></tr><tr><td>マイクが合っているか</td><td>設定 &gt; 話す &gt; マイク で、実際に話すマイクを選びます</td></tr><tr><td>Windowsがマイクを許可しているか</td><td>Windowsの 設定 &gt; プライバシーとセキュリティ &gt; マイク で、「デスクトップ アプリがマイクにアクセスできるようにする」がオンか確認します</td></tr><tr><td>モデルをダウンロードしたか</td><td>このPCで動くエンジンは、最初にダウンロードが必要です。設定 &gt; そのほか &gt; モデルと容量 で確認します</td></tr><tr><td>「音声認識サービスに接続できません」と出る</td><td>クラウドのエンジンは、ネットワークや提供元の都合で途切れることがあります。設定 &gt; 話す &gt; 言語と認識 で、このPCで動くエンジンに変えます(<a href="/Mutelink-releases/compare/speech-recognition">比較</a>)</td></tr><tr><td>エンジンが、その言語に対応しているか</td><td>Parakeet 日本語 TDTとHaas-jaは日本語だけ、Parakeet 英語は日本語を聞き取れません</td></tr><tr><td>特定の言葉だけ出ない</td><td>除外する言葉の設定に入っていないか確認します</td></tr></tbody></table><p><img src="'+r+'" alt="Windowsのマイクのプライバシー設定"></p><h2 id="ダウンロードが失敗する" tabindex="-1">ダウンロードが失敗する <a class="header-anchor" href="#ダウンロードが失敗する" aria-label="Permalink to &quot;ダウンロードが失敗する&quot;">​</a></h2><p>失敗したときは、画面に原因が出ます。途中まで進んだ分は残るので、もう一度ダウンロードを押すと、続きから再開します。</p><table tabindex="0"><thead><tr><th>表示</th><th>対処</th></tr></thead><tbody><tr><td>通信が切れた、止まった</td><td>ネットワークを確認して、もう一度押します</td></tr><tr><td>ダウンロード元にファイルが見つからない</td><td>配布元が変わった可能性があります。アプリを最新にします(設定 &gt; そのほか &gt; アプリについて)</td></tr><tr><td>ダウンロード元のサーバーが応答しない</td><td>一時的な障害のことがあります。しばらくしてから、もう一度押します</td></tr><tr><td>ファイルが壊れていた</td><td>壊れたファイルは自動で消えています。もう一度ダウンロードします</td></tr><tr><td>空き容量が足りない</td><td>空きを作ってから、もう一度押します。容量は、設定 &gt; そのほか &gt; モデルと容量 で確認できます</td></tr></tbody></table><p>途中まで進んだ分を消したいときは、設定 &gt; そのほか &gt; モデルと容量 で消せます。</p><h2 id="irodori-tts・qwen3-ttsが動かない" tabindex="-1">Irodori-TTS・Qwen3-TTSが動かない <a class="header-anchor" href="#irodori-tts・qwen3-ttsが動かない" aria-label="Permalink to &quot;Irodori-TTS・Qwen3-TTSが動かない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>GPUがVulkanに対応しているか</td><td>Vulkanに対応したGPUとドライバが必要です。GPUのドライバを最新にします</td></tr><tr><td>VRAMが足りているか</td><td>VRChatや、このPCで動く翻訳と、VRAMを分け合います。足りないときは、VRChatの画質を下げるか、翻訳をCPUで動かすか、VOICEVOXを使います</td></tr><tr><td>最初の読み上げだけ遅い</td><td>最初にモデルを読み込むためです。起動の直後や、声を切り替えた直後は、少し待ちます</td></tr><tr><td>切り替えに時間がかかる</td><td>Irodori-TTSとQwen3-TTSは、同時に1つだけ読み込みます。出力の言語を変えると、入れ替えに数秒かかることがあります</td></tr></tbody></table><h2 id="翻訳されない" tabindex="-1">翻訳されない <a class="header-anchor" href="#翻訳されない" aria-label="Permalink to &quot;翻訳されない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>翻訳する組み合わせになっているか</td><td>話す言語と、出力の言語が違うときだけ翻訳します</td></tr><tr><td>使える翻訳エンジンがあるか</td><td>設定 &gt; 翻訳 で、Azure Translatorのキーを入れるか、PLaMoかTranslateGemmaをダウンロードします(<a href="/Mutelink-releases/compare/translation">比較</a>)</td></tr><tr><td>Azureのキーとリージョン</td><td><a href="/Mutelink-releases/guide/azure-translator#うまくいかないとき">Azure Translatorの導入</a>を見てください</td></tr><tr><td>訳したのに声が出ない</td><td>訳した文の読み上げは、<a href="/Mutelink-releases/about/supporter">支援版</a>の機能です。その言語を読める声(日本語以外はQwen3-TTS)も必要です</td></tr></tbody></table><p>翻訳に失敗した文は、原因のお知らせが出て、原文のままチャットボックスにだけ送られます。</p><h2 id="聞こえた声が出ない" tabindex="-1">聞こえた声が出ない <a class="header-anchor" href="#聞こえた声が出ない" aria-label="Permalink to &quot;聞こえた声が出ない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>聞き取りがオンか</td><td>メイン画面の👂のボタンで、聞き取りを始めます</td></tr><tr><td>VRChatが起動しているか</td><td>聞き取るのは、設定 &gt; 聞く &gt; 聞こえた声 で指定したアプリ(初期値はVRChat)の音だけです。起動していないときは、起動を待ちます</td></tr><tr><td>モデルをダウンロードしたか</td><td>設定 &gt; そのほか &gt; モデルと容量 で確認します</td></tr><tr><td>BGMが鳴り続けている</td><td>声の区切りが付かないことがあります。設定 &gt; 聞く &gt; 聞こえた声 で、声の検出を厳しくします</td></tr><tr><td>自分の読み上げが出ない</td><td>Mutelink自身の読み上げの音は、取り込みません</td></tr></tbody></table><h2 id="vrの中に画面が出ない" tabindex="-1">VRの中に画面が出ない <a class="header-anchor" href="#vrの中に画面が出ない" aria-label="Permalink to &quot;VRの中に画面が出ない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>確認すること</th><th>対処</th></tr></thead><tbody><tr><td>SteamVRが起動しているか</td><td>Mutelinkは、数秒ごとに自動でSteamVRにつなぎ直します。出ないときは、SteamVRを起動した状態で、Mutelinkを起動し直します</td></tr><tr><td>ほかのオーバーレイアプリ</td><td>ほかのSteamVRのオーバーレイアプリと、ボタンの割り当てが重なっていないか確認します</td></tr><tr><td>手の甲に出したい</td><td>パネルを手に付けるには、<a href="/Mutelink-releases/about/supporter">支援版</a>(カスタマイズ拡張)が必要です。無いときは、視界に出ます</td></tr></tbody></table><h2 id="アプリが起動しない" tabindex="-1">アプリが起動しない <a class="header-anchor" href="#アプリが起動しない" aria-label="Permalink to &quot;アプリが起動しない&quot;">​</a></h2><p>最新のバージョンを入れ直して、Windowsを再起動してから試してください。それでも起動しないときは、BOOTHのメッセージ、または作者のXアカウント(<a href="https://x.com/nktssbat" target="_blank" rel="noreferrer">@nktssbat</a>、<a href="https://x.com/yuki54625" target="_blank" rel="noreferrer">@yuki54625</a>)まで知らせてください。</p>',31)])])}const V=d(i,[["render",l]]);export{C as __pageData,V as default};
